"""Inspected source passages and retrieval limitations for the research snapshot."""
ASOF='2026-11-16'
sources=[]
retrievals=[]
def src(n,title,author,url,date,kind,locator,passage,note='',origin=None):
    sid=f'S{n:03d}'; rid=f'R{n:03d}'
    origin=origin or author+' | '+title
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':date,'URL':url,'Access date':ASOF,'Source class':kind,'Primary or secondary':'Primary' if kind in ['Official record','Court or commission','Speech or primary statement','Party or campaign','Statute'] else 'Secondary','Access status':'Passage inspected','Origin ID':origin,'Locator':locator,'Reliability / limitation note':note or 'Supports the specified passage, not every claim about the subject.','Geographic / language scope':'India / English'})
    retrievals.append({'id':rid,'source_id':sid,'url':url,'access_date':ASOF,'route':'Canonical page or identified document reproduction','access_status':'Passage inspected','origin_id':origin,'locator':locator,'passage_paraphrase':passage,'method':'Web page/PDF passage read; local PDF text used for S001 and downloaded HTML for S028','result':'Relevant passage inspected','next_action':'Reuse unless wording or cutoff changes'})

src(1,'Rajya Sabha Who’s Who 2020: Ramesh, Shri Jairam','Rajya Sabha Secretariat','https://cms.rajyasabha.nic.in/UploadedFiles/ElectronicPublications/larrdis/WhosWho_2020.pdf','2020','Official record','Printed pp.379–381; PDF pp.412–414','Born 9 April 1954, Chikmagalur; B.Tech., M.S., graduate study at IIT Bombay, Carnegie Mellon and MIT. Lists 2004/2010/2016 elections; Commerce 31 January 2006–25 February 2009; Power 6 April 2008–25 February 2009; Environment 28 May 2009–12 July 2011; Rural Development 12 July 2011–26 May 2014; Drinking Water additional charge 13 July 2011–28 October 2012. Resigned second RS term effective 20 June 2016. Committee and earlier advisory roles listed.','Historical official biography; current-office claims require later evidence. Some secondary biographies give different rural/sanitation dates; this register uses these explicit dates.')
src(2,'CV: Jairam Ramesh','Biographical CV hosted by Asian Development Bank','https://aric.adb.org/pdf/spotlight%20documents/CV_Jairam%20Ramesh.pdf',None,'Official record','Single-page CV, paragraphs 1–4','Describes involvement in the 2004 Congress strategy team and UPA Common Minimum Programme; NAC membership; Karnataka Planning Board 2000–02, Rajasthan council 1999–2003, Chhattisgarh advice 2001–03; PM adviser 1991, adviser to Planning Commission deputy chairman 1992–94 and finance minister 1996–98.','Promotional participant CV; establishes claimed roles, not sole authorship or results. Planning role was adviser to deputy chairman, not deputy chairman of the national commission.')
src(3,'Bio Data of Shri Jairam Ramesh, Minister of State of Environment and Forests','Press Information Bureau / Environment Ministry','https://www.pib.gov.in/newsite/erelcontent.aspx?lang=2&reg=48&relid=48930','2009-05-29','Official record','Biographical paragraphs on assignments and communication','Lists energy-policy assignments 1983–85, CSIR reorganisation 1986 and technology missions 1987–89; reports economic journalism and television work.','The compressed sentence on the Planning Commission is ambiguous; S002 resolves the adviser role. Promotional claims of popularity are not adopted.')
src(4,'Jairam Ramesh — MP Track','PRS Legislative Research','https://prsindia.org/mptrack/rajya-sabha/jairamramesh',None,'Dataset','Profile and data-period heading','Lists INC, Karnataka, elected fourth term beginning 1 July 2022, in office. Activity window is 1 June 2009–13 August 2026.','Secondary parliamentary compilation. Aggregate activity metrics over a mixed-tenure window are not used as an effectiveness ranking.')
src(5,'Communication Department','Indian National Congress','https://inc.in/aicc-depts-cells/communication-department',None,'Party or campaign','Department heading and Jairam Ramesh entry','Lists Ramesh as general secretary responsible for communication, publicity and media including social and digital media.','Party directory establishes party assignment; not independent evaluation.')
src(6,'Ramesh elected to RS from AP','PTI / Governance Now','https://www.governancenow.com/gov-now/your-mp/ramesh-elected-rs-ap','2010-06-07','Journalism','Opening and list of six elected candidates','Reports Jairam Ramesh and five others elected unopposed from Andhra Pradesh on 7 June 2010.','Later paragraph about losing Bapatla refers to J. D. Seelam, not Ramesh; its SC-quota wording must not be treated as a statutory reserved Rajya Sabha seat.')
