for rid,sid,url,result in [
 ('R001-fail','S001',sources[0]['URL'],'Sandbox DNS failure; approved direct retrieval subsequently succeeded.'),
 ('R028-web','S028','https://www.pib.gov.in/newsite/PrintRelease.aspx?lang=2&reg=3&relid=88045','Web cache miss; official direct HTML subsequently retrieved.'),
 ('R028-mirror','S028','https://www.pib.gov.in/newsite/erelcontent.aspx?relid=88045','Alternate web-reader route inaccessible; direct canonical HTML succeeded.')]:
    retrievals.append({'id':rid,'source_id':sid,'url':url,'access_date':ASOF,'route':'Attempt before successful retrieval','access_status':'Failed retrieval','origin_id':next(s['Origin ID'] for s in sources if s['Source ID']==sid),'locator':'None','passage_paraphrase':'','method':'Web reader or curl','result':result,'next_action':'Resolved by recorded successful route; do not repeat.'})
